<script setup lang="ts">const props=defineProps<{item:{id:string;number:number;title:string;severity:string;state:string;service_key:string;impact_summary:string;error_budget_remaining_bps:number;events?:{type:string;summary:string;created_at:string}[]}|null}>();const emit=defineEmits<{transition:[value:{current:string;next:string;severity:string;summary:string}]}>();const next=ref('triaged'),summary=ref('اثر رخداد بررسی شد و اقدام بعدی طبق Runbook آغاز می‌شود.');watch(()=>props.item?.state,(state:string|undefined)=>{next.value=state==='detected'?'triaged':state==='triaged'?'mitigating':state==='mitigating'?'monitoring':state==='monitoring'?'resolved':'closed'},{immediate:true});function submit(){if(props.item)emit('transition',{current:props.item.state,next:next.value,severity:props.item.severity,summary:summary.value})}</script>
<template><section v-if="item" class="sre-panel"><header class="sre-incident-header"><div><p>رخداد #{{item.number.toLocaleString('fa-IR')}}</p><h2>{{item.title}}</h2></div><span class="sre-severity" :data-level="item.severity">{{item.severity.toUpperCase()}}</span></header><p>{{item.impact_summary}}</p><ErrorBudgetPanel :remaining="item.error_budget_remaining_bps" :service="item.service_key"/><h3>خط زمانی قابل ممیزی</h3><ol class="sre-timeline"><li v-for="event in item.events" :key="`${event.type}-${event.created_at}`"><b>{{event.summary}}</b><small>{{new Date(event.created_at).toLocaleString('fa-IR')}}</small></li></ol><form class="sre-transition" @submit.prevent="submit"><label>وضعیت بعدی<select v-model="next"><option value="triaged">ارزیابی‌شده</option><option value="mitigating">مهار</option><option value="monitoring">پایش</option><option value="resolved">رفع‌شده</option><option value="closed">بسته‌شده</option></select></label><label>خلاصه اقدام<input v-model="summary" minlength="12" maxlength="500" required></label><button class="button button-primary" type="submit">ثبت در خط زمانی</button></form></section><section v-else class="sre-panel"><p>رخدادی برای نمایش انتخاب نشده است.</p></section></template>
